        fprintf(stderr, "Failed to open output file\n");
        sqlite3_finalize(res);
        sqlite3_close(db);
        return 1;
    }

    while (sqlite3_step(res) == SQLITE_ROW) {
        int u1 = sqlite3_column_int(res, 0);
        int u2 = sqlite3_column_int(res, 1);
        fprintf(f, "CREATE (u1:User {id: %d})-[:CONNECTED_ACTIVE]->(u2:User {id: %d})\n", u1, u2);
    }

    fclose(f);
    sqlite3_finalize(res);
    sqlite3_close(db);

    return 0;
}
EOF
